dashboard.definition:
{
    "title": "Cisco IQ – Assets, Lifecycle und Sicherheit",
    "description": "Cisco IQ: Asset-Inventar, betroffene Geraete je PSIRT-Advisory, Lifecycle-Meilensteine, Vertragsabdeckung und Field Notices",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_building": {
            "type": "input.dropdown",
            "title": "Haus",
            "options": {
                "items": [
                    {
                        "label": "Alle Haeuser",
                        "value": "*"
                    },
                    {
                        "label": "Haus A - Innere Medizin",
                        "value": "A"
                    },
                    {
                        "label": "Haus B - Chirurgisches Zentrum",
                        "value": "B"
                    },
                    {
                        "label": "Haus C - Akut- und Intensivzentrum",
                        "value": "C"
                    },
                    {
                        "label": "Haus D - Frauen, Kind und Psyche",
                        "value": "D"
                    }
                ],
                "token": "building",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "advisory": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_assets": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:iq:asset\" building=\"$building$\" earliest=-7h\n| stats latest(productId) as productId latest(productFamily) as productFamily latest(softwareVersion) as softwareVersion latest(role) as role latest(building) as building latest(lifecycleStage) as lifecycleStage latest(lastDateOfSupport) as lastDateOfSupport latest(endOfSaleDate) as endOfSaleDate latest(coverageStatus) as coverageStatus latest(contractNumber) as contractNumber latest(serviceLevel) as serviceLevel latest(coverageEndDate) as coverageEndDate by hostname",
                "enableSmartSources": true
            },
            "name": "Cisco IQ Assets"
        },
        "ds_k_assets": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_assets",
                "query": "| stats count as Assets"
            }
        },
        "ds_k_eos": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_assets",
                "query": "| where lifecycleStage=\"End of Support\" | stats count as \"End of Support\""
            }
        },
        "ds_k_nocov": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_assets",
                "query": "| where coverageStatus=\"Not Covered\" | stats count as \"Ohne Vertrag\""
            }
        },
        "ds_k_exp": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_assets",
                "query": "| where coverageStatus=\"Expiring\" | stats count as \"Vertrag laeuft ab\""
            }
        },
        "ds_adv": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:iq:advisory\" building=\"$building$\" earliest=-7h\n| fields CVSS Geraet Haus Schwere Titel _time advisoryId building count cves{}* cvssBaseScore firstPublished fixedVersion hostname productId sev severity softwareVersion title",
                "enableSmartSources": true
            },
            "name": "Advisories"
        },
        "ds_k_crit": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_adv",
                "query": "| where severity=\"Critical\" | stats dc(hostname) as \"Kritisch betroffen\""
            }
        },
        "ds_k_fn": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:iq:fieldnotice\" status=\"Potentially Vulnerable\" earliest=-7h | stats dc(hostname) as \"Field Notices\"",
                "enableSmartSources": true
            }
        },
        "ds_adv_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_adv",
                "query": "| stats latest(title) as Titel latest(severity) as Schwere max(cvssBaseScore) as CVSS dc(hostname) as Betroffen latest(fixedVersion) as \"Fix in\" values(cves{}) as CVE latest(firstPublished) as Veroeffentlicht by advisoryId\n| eval sev=case(Schwere=\"Critical\", 0, Schwere=\"High\", 1, true(), 2) | sort sev - CVSS | fields - sev | rename advisoryId as Advisory\n| appendpipe [| stats count | where count=0 | eval Titel=\"Keine Advisories im letzten Cisco-IQ-Snapshot\" | fields - count]"
            }
        },
        "ds_affected": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_adv",
                "query": "| search advisoryId=\"$advisory$\"\n| stats latest(productId) as Modell latest(softwareVersion) as Software latest(fixedVersion) as \"Fix in\" latest(severity) as Schwere values(advisoryId) as Advisory latest(building) as Haus by hostname\n| rename hostname as Geraet | sort Haus Geraet\n| appendpipe [| stats count | where count=0 | eval Geraet=\"Keine betroffenen Geraete im letzten Cisco-IQ-Snapshot\" | fields - count]"
            }
        },
        "ds_lifecycle": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_assets",
                "query": "| stats count by lifecycleStage"
            }
        },
        "ds_coverage": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_assets",
                "query": "| stats count by coverageStatus"
            }
        },
        "ds_family": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_assets",
                "query": "| stats count as Geraete by productId | sort - Geraete | head 12 | rename productId as Modell"
            }
        },
        "ds_eol": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_assets",
                "query": "| where lifecycleStage!=\"Active\"\n| stats count as Geraete values(building) as Haeuser by productId lifecycleStage endOfSaleDate lastDateOfSupport\n| rename productId as Modell lifecycleStage as Lifecycle endOfSaleDate as \"End of Sale\" lastDateOfSupport as \"Last Date of Support\""
            }
        },
        "ds_contracts": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:iq:contract\" earliest=-7h | stats latest(serviceLevel) as Servicelevel latest(coverageEndDate) as \"Laeuft bis\" latest(devicesCovered) as Geraete latest(status) as Status by contractNumber | rename contractNumber as Vertrag",
                "enableSmartSources": true
            }
        },
        "ds_fn": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"cisco:iq:fieldnotice\" earliest=-7h | stats dc(hostname) as Geraete latest(title) as Titel by fieldNoticeId status | rename fieldNoticeId as \"Field Notice\" status as Status",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/nav_home.svg",
                "preserveAspectRatio": true
